/* Functional test client. All shared writes use the verified LINE identity on GAS. */
'use strict';
const CONFIG={liffId:'2012504695-oSmM1JBO',api:'https://script.google.com/macros/s/AKfycbw4UACUX9iF7v09H6gcsfct7XXvyrlYMA2C1HnOKQFirHL3604BkVITIIczcXldfmNF/exec'};
const C=StudyCore,$=id=>document.getElementById(id),q=new URLSearchParams(location.search),family=q.get('demo')==='family',demo=q.get('demo')==='1'||family;
const role=q.get('role')==='teacher'?'teacher':'student';
const S={role,actor:null,students:[],studentId:null,page:role==='teacher'?'students':'today',date:jstToday(),busy:false,error:'',wizard:null,planId:null,teacherSettings:C.empty().teacherSettings,savedAt:null,ready:false,pdf:null,pdfHandoffApplied:false};
function jstToday(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function btn(label,action,cls='action',data={}){return '<button type="button" class="'+cls+'" data-action="'+action+'" '+Object.entries(data).map(([k,v])=>'data-'+k+'="'+esc(v)+'"').join(' ')+'>'+esc(label)+'</button>'}
function field(label,name,value='',type='text',extra=''){return '<label class="field">'+esc(label)+'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" '+extra+'></label>'}
function select(label,name,values,value){return '<label class="field">'+esc(label)+'<select name="'+name+'">'+values.map(v=>{const a=Array.isArray(v)?v:[v,v];return '<option value="'+esc(a[0])+'" '+(String(a[0])===String(value)?'selected':'')+'>'+esc(a[1])+'</option>'}).join('')+'</select></label>'}
function card(title,html){return '<section class="card"><h3>'+esc(title)+'</h3>'+html+'</section>'}
function hint(s){return '<p class="formhint">'+esc(s)+'</p>'}
function item(){return S.students.find(s=>s.studentId===S.studentId)||null}
function doc(){return item()?.doc||C.empty()}
function plan(){return doc().plans.find(p=>p.id===(S.planId||doc().activeId))||C.active(doc())}
function modeLabel(r){return !r?'未記録':r.mode==='done'?'完了':r.mode==='none'?'取り組まなかった':'途中まで · '+r.position+'まで'}
function pct(p,d){if(!p||!p.tasks.length)return 0;return Math.round(p.tasks.filter(t=>d.records[t.id]?.mode==='done').length/p.tasks.length*100)}
function progress(n){return '<div class="bar" role="progressbar" aria-label="完了した予定の割合" aria-valuenow="'+n+'" aria-valuemin="0" aria-valuemax="100"><span style="width:'+n+'%"></span></div>'}
function navBack(page='plan'){return btn('‹ 戻る','page','back',{page})}
function draftKey(){return 'manabi-draft-v2:'+S.role+':'+S.studentId}
function saveDraft(){if(S.wizard)localStorage.setItem(draftKey(),JSON.stringify(S.wizard))}
function newDraft(){return {step:0,input:{type:'test',title:'',target:'',start:S.date,goal:C.add(S.date,14),materials:[{name:'',subject:'数学',from:1,to:20,unit:'ページ',minutes:10}],availability:[30,30,30,30,30,60,0],hwWeekly:'ほとんどない',reserveDay:'',busyNote:'',busyDates:[]},rebuildId:null}}
async function api(source,params={}){
 if(demo)return demoApi(source,params);
 const payload={source,role:S.role,...params,idToken:liff.getIDToken(),accessToken:liff.getAccessToken()};
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);let r,j;
 try{r=await fetch(CONFIG.api,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload),signal:controller.signal});if(!r.ok)throw Error('接続エラーです。時間をおいて再試行してください');const text=await r.text();try{j=JSON.parse(text)}catch{throw Error('保存APIが未更新か、接続に失敗しました。管理者に確認してください')}}finally{clearTimeout(timer)}
 if(!j.ok){if(j.code==='CONFLICT'&&j.item)replaceItem(j.item);throw Error(j.code?.startsWith('AUTH_')?'LINEの認証が切れました。画面を開き直してください':j.error||'保存できませんでした')}return j;
}
function demoApi(source,p){
 // ?demo=1：1人のデモ。?demo=family：保護者（母）のLINEに、2人の生徒（兄弟）が付いているデモ。どちらも、このブラウザの中だけに保存する
 const ids=family?['S2','S3']:['DEMO'],keyOf=id=>'manabi-functional-demo-v1'+(family?':'+id:'');
 const load=id=>{const st=JSON.parse(localStorage.getItem(keyOf(id))||'null')||{studentId:id,name:family?id:'テスト生徒',revision:0,doc:C.empty()};if(family)st.relation='母';st.doc=C.resume(st.doc,S.date);return st};
 if(source==='app_boot')return {ok:true,actor:{id:'DEMO',name:'テスト利用',role:S.role},students:ids.map(load),teacherSettings:JSON.parse(localStorage.getItem('manabi-functional-demo-v1teacher')||'null')||C.empty().teacherSettings,today:jstToday()};
 if(source==='app_teacher_settings'){localStorage.setItem('manabi-functional-demo-v1teacher',JSON.stringify(p.settings));return {ok:true,settings:p.settings}}
 if(source==='app_action'){const store=load(p.studentId||ids[0]);if(p.revision!==store.revision){replaceItem(store);throw Error('別の画面で更新されています。もう一度操作してください')}store.doc=C.apply(store.doc,p.action,{name:'テスト講師',role:S.role,relation:store.relation||''},{id:crypto.randomUUID(),today:S.date,now:new Date().toISOString()});store.revision++;localStorage.setItem(keyOf(store.studentId),JSON.stringify(store));return {ok:true,item:store}}
 throw Error('デモでは利用できない操作です')}
function replaceItem(it){const i=S.students.findIndex(s=>s.studentId===it.studentId);if(i<0)S.students.push(it);else S.students[i]=it}
async function busy(job,msg='保存しました'){if(S.busy)return;S.busy=true;S.error='';renderStatus();const key=formDraftKey(),buttons=Array.from(document.querySelectorAll('button')).map(b=>[b,b.disabled]);buttons.forEach(([b])=>b.disabled=true);let okay=false;try{await job();okay=true}catch(e){S.error=e.name==='AbortError'?'応答を確認できませんでした。入力は残っています。「最新のデータを読み込む」で、保存されたか確認してください':e.message}finally{S.busy=false;if(S.error){buttons.forEach(([b,disabled])=>b.disabled=disabled);renderStatus();window.scrollTo(0,0)}else{try{sessionStorage.removeItem(key)}catch{}render()}}if(okay&&msg)showToast(msg)}
function showToast(m){const t=$('toast');t.textContent=m;t.hidden=false;clearTimeout(showToast.t);showToast.t=setTimeout(()=>{t.hidden=true},2400)}
// 入力した内容が、画面の再表示で消えないように、この端末の中に、一時的に残す（保存できたら消す）
function formDraftKey(){return 'manabi-form:'+S.role+':'+(S.studentId||'')+':'+S.page}
function saveFormDraft(e){const t=e.target;if(!t||!t.name||S.page==='wizard'||t.type==='password')return;try{const k=formDraftKey(),o=JSON.parse(sessionStorage.getItem(k)||'{}');o[t.name]=t.type==='checkbox'?t.checked:t.value;sessionStorage.setItem(k,JSON.stringify(o))}catch{}}
function restoreFormDraft(){if(S.page==='wizard')return;try{const o=JSON.parse(sessionStorage.getItem(formDraftKey())||'{}');Object.entries(o).forEach(([n,v])=>{const el=$('content').querySelector('[name="'+n+'"]');if(!el||el.disabled||el.type==='hidden')return;if(el.type==='checkbox')el.checked=!!v;else el.value=v})}catch{}}
async function boot(){const result=await api('app_boot');S.actor=result.actor;S.students=result.students;S.date=result.today;S.selectedDate=S.selectedDate||S.date;S.teacherSettings=result.teacherSettings||S.teacherSettings;if(!S.students.some(s=>s.studentId===S.studentId))S.studentId=S.students[0]?.studentId;if(!S.pdfHandoffApplied&&q.get('view')==='pdf'){const requested=q.get('plan');if(requested){const owner=S.students.find(it=>it.doc.plans.some(p=>p.id===requested));if(!owner)throw Error('この計画が見つかりません。作成したLINEアカウントで開いてください');S.studentId=owner.studentId;S.planId=requested}S.page='pdf';S.pdfHandoffApplied=true}S.ready=true;S.savedAt=new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'});render()}
async function mutate(action){const current=item();if(!current)throw Error('生徒を選んでください');const requestId=crypto.randomUUID();const result=await api('app_action',{studentId:current.studentId,revision:current.revision,requestId,action});replaceItem(result.item);S.savedAt=new Date().toLocaleTimeString('ja-JP',{hour:'2-digit',minute:'2-digit'})}
function renderStatus(){$('busy').hidden=!S.busy;$('error').hidden=!S.error;$('error').innerHTML=esc(S.error)+(!S.error?'':'<div>'+btn('最新のデータを読み込む','refresh','secondary')+'</div>');const st=$('status'),msg=demo?'動作デモ：入力は、このブラウザの中にだけ保存されます':'';st.hidden=!msg;st.textContent=msg}
function render(){renderStatus();const title={students:'担当の生徒',detail:'生徒の進み具合',today:'今日やること',plan:'計画',settings:'通知の設定',teacherSettings:'講師の通知設定',wizard:'計画をつくる',edit:'計画を直す',history:'変更の履歴',report:'進み具合を記録',editTask:'予定を直す',skip:'休む・別の日に回す',pdf:'PDFで保存',feedback:'ひとことを送る',answers:'回答の確認',roadmap:'月ごとの道筋',upper:'教材ごとの期間'};document.title=title[S.page]||'学習計画';
 if(!S.ready){$('content').innerHTML='<div class="empty">LINEでの接続を待っています。<br>つながらないときは、下のボタンを押してください。</div>'+btn('接続をやり直す','refresh','primary');$('nav').innerHTML='';return}
 const views={students:studentsView,detail:detailView,today:todayView,plan:planView,settings:settingsView,teacherSettings:teacherSettingsView,wizard:wizardView,edit:editView,history:historyView,report:reportView,editTask:editTaskView,skip:skipView,pdf:pdfView,feedback:feedbackView,roadmap:roadmapView,upper:upperView};$('content').innerHTML=eyebrow()+identityBar()+(views[S.page]||todayView)();
 $('nav').innerHTML=S.page==='wizard'?'':S.role==='teacher'?btn('生徒','page',S.page==='students'||S.page==='detail'?'on':'',{page:'students'})+btn('通知','page',S.page==='teacherSettings'?'on':'',{page:'teacherSettings'}):btn('☀ 今日','page',S.page==='today'?'on':'',{page:'today'})+btn('▤ 計画','page',S.page!=='today'&&S.page!=='wizard'?'on':'',{page:'plan'});
 document.querySelectorAll('#nav .on').forEach(b=>b.setAttribute('aria-current','page'));restoreFormDraft();
}
// 画面の最上部に出す、現在地（どの画面にいるか）
function eyebrow(){const t=S.role==='teacher',who=item()?item().name:'',m={today:'今日',plan:'計画',settings:'計画 › 通知の設定',edit:'計画 › 計画を直す',history:'計画 › 変更の履歴',skip:'今日 › 休む・別の日に回す',pdf:'計画 › PDFで保存',upper:'計画 › 教材ごとの期間',editTask:'計画 › 予定を直す',roadmap:'計画 › 月ごとの道筋',report:'今日 › 記録',wizard:'計画をつくる',students:'生徒',teacherSettings:'通知',detail:'生徒 › '+who,feedback:'生徒 › '+who+' › ひとこと'};
 if(t){m.plan='生徒 › '+who+' › 計画';m.edit='生徒 › '+who+' › 計画を直す';m.history='生徒 › '+who+' › 変更の履歴';m.upper='生徒 › '+who+' › 教材ごとの期間';m.roadmap='生徒 › '+who+' › 月ごとの道筋';m.settings='通知'}
 const label=m[S.page];return label?'<p class="eyebrow" aria-hidden="true">'+esc(label)+'</p>':''}
function relationLabel(r){return r==='母'||r==='父'?'保護者（'+r+'）':r==='本人'?'生徒本人':''}
// 生徒の画面の上に出す：保護者としてログイン中の表示と、生徒の切り替え（1つのLINEに、複数の生徒が付くとき）
function identityBar(){
 if(S.role!=='student'||!S.ready)return '';const it=item();if(!it)return '';const rel=it.relation,parent=rel==='母'||rel==='父';let h='';
 if(parent)h+='<div class="identity" role="status">'+esc(relationLabel(rel))+'として、<b>'+esc(it.name)+'</b>さんの画面を表示中</div>';
 if(S.students.length>1)h+='<div class="switcher" role="group" aria-label="お子さんを選ぶ"><div class="plans">'+S.students.map(x=>btn(x.name,'pickStudent',x.studentId===S.studentId?'sel':'',{id:x.studentId})).join('')+'</div></div>';
 return h;
}

// ---------- 受験逆算：計画づくりの設定／上段（教材ごとの期間）の表示と調整／月1回の見直し ----------
const JC=typeof JukenCore!=='undefined'?JukenCore:null;
function jukenDraft(){return {subjects:['英語','数学(理)'],owned:[],others:[],othersNames:[],autoTasks:true,mockType:'河合',mockScore:'',examYm:'',dev:null,band:null,univ:''}}
function jukenStep(w){
 const a=w.input,j=a.juken=a.juken||jukenDraft();if(!JC||!window.JukenUniv)return hint('受験逆算のデータを読み込めませんでした。画面を開き直してください。');
 const univRows=(w.univResults||[]).map((r,i)=>'<div class="resultrow"><span>'+esc(r.univ+' '+r.dept)+'<small>'+(r.dev!=null?'偏差値'+r.dev:'')+'</small></span><span class="rb">'+btn('第1志望にする','pickUniv','secondary',{i})+btn('併願に足す','pickOther','secondary',{i})+'</span></div>').join('');
 const ownRows=(w.ownResults||[]).map(r=>btn(r.name,'pickOwn','action',{id:r.id})).join('');
 return '<h3 class="sec-title">第1志望</h3>'+(j.univ?'<div class="notice"><b>'+esc(j.univ)+'</b></div>':'')+(j.univ?'<details class="more sm" '+(univRows?'open':'')+'><summary>志望校を変える</summary>':'')+'<div class="inlinefields search">'+field('大学名（例：東大）','univq',w.univq||'')+btn('探す','searchUniv','secondary')+'</div>'+univRows+(j.univ?'</details>':'')+field('志望校の偏差値','dev',j.dev==null?'':j.dev,'number','min="30" max="85" step="0.5" inputmode="decimal"')
 +(j.othersNames.length?'<h3 class="sec-title">併願校</h3>':'')+(j.othersNames.length?j.othersNames.map((n,i)=>'<div class="kv"><span>'+esc(n)+'</span>'+btn('外す','removeOther','linkbtn',{i})+'</div>').join(''):'')
 +'<h3 class="sec-title">入試と、今の学力</h3>'+'<label class="field">入試の年月<select name="examYm" required><option value="">選んでください</option>'+(()=>{const y0=Number(S.date.slice(0,4)),m0=Number(S.date.slice(5,7)),o=[];for(let k=0;k<40;k++){const m=(m0-1+k)%12+1,y=y0+Math.floor((m0-1+k)/12),v=y+'-'+String(m).padStart(2,'0');o.push('<option value="'+v+'" '+(j.examYm===v?'selected':'')+'>'+y+'年'+m+'月</option>')}return o.join('')})()+'</select></label>'+'<div class="inlinefields">'+select('模試の種類','mockType',['河合','東進','進研','駿台'],j.mockType)+field('いまの偏差値','mockScore',j.mockScore,'number','min="20" max="85" step="0.5" inputmode="decimal"')+'</div>'
 +'<h3 class="sec-title">勉強する科目</h3>'+(()=>{const all=JC.subjectsOf?JC.subjectsOf():[],box=x=>'<label class="checkrow"><input type="checkbox" name="subj" value="'+esc(x)+'" '+(j.subjects.includes(x)?'checked':'')+'> '+esc(x)+'</label>',top=all.slice(0,6),rest=all.slice(6);return '<div class="grid2">'+top.map(box).join('')+'</div>'+(rest.length?'<details class="more" '+(rest.some(x=>j.subjects.includes(x))?'open':'')+'><summary>ほかの科目を選ぶ</summary><div class="grid2">'+rest.map(box).join('')+'</div></details>':'')})()
 +'<details class="more sm" '+(j.owned.length||w.ownq?'open':'')+'><summary>手持ちの教材を入れる（なくてもOK）</summary>'+(j.owned.length?j.owned.map((o,i)=>'<div class="kv"><span>'+esc(o.name)+'</span>'+btn('外す','removeOwn','linkbtn',{i})+'</div>').join(''):'')+'<div class="inlinefields search">'+field('教材名で探す','ownq',w.ownq||'')+btn('探す','searchOwn','secondary')+'</div>'+ownRows+(w.ownq?btn('「'+w.ownq+'」を、名前だけで足す','addOwnFree','secondary'):'')+'</details>';
}
function jukenSummary(a){const j=a.juken||{};return kvr('志望校',esc(j.univ||'未選択')+(j.othersNames&&j.othersNames.length?'<br><span class="caption">併願：'+esc(j.othersNames.join('、'))+'</span>':''))+kvr('入試',esc(j.examYm||''))+kvr('いまの学力',j.mockScore!==''&&j.mockScore!=null?esc(j.mockType||'')+' 偏差値'+j.mockScore:'未入力')+kvr('科目',esc((j.subjects||[]).join('、')))+(j.owned&&j.owned.length?kvr('手持ち',esc(j.owned.map(o=>o.name).join('、'))):'')}
function jukenCapture(data,w){
 const j=w.input.juken=w.input.juken||jukenDraft();w.univq=data.get('univq')||'';w.ownq=data.get('ownq')||'';
 j.examYm=data.get('examYm')||'';j.mockType=data.get('mockType')||'河合';j.mockScore=data.get('mockScore')===''||data.get('mockScore')==null?'':Number(data.get('mockScore'));
 const dv=data.get('dev');j.dev=dv===''||dv==null?null:Number(dv);j.subjects=data.getAll('subj');
}
function wizardSteps(a){return a.type==='juken'?[0,3,4,5]:a._skipMat?[0,1,2,4,5]:[0,1,2,3,4,5]}
function nextStep(w,dir){const st=wizardSteps(w.input),i=st.indexOf(w.step);return st[Math.min(st.length-1,Math.max(0,(i<0?0:i)+dir))]}
function jukenInput(a){const j=a.juken,end=C.add(S.date,180),exam=(j.examYm||'')+'-15';return {...a,title:'大学受験'+(j.univ?'：'+j.univ:''),target:a.target||'',start:S.date,goal:exam>S.date&&exam<end?exam:end,materials:[],juken:{band:j.band,examYm:j.examYm,univ:j.univ,dev:j.dev,mockType:j.mockScore===''||j.mockScore==null?'':j.mockType,mockScore:j.mockScore===''?null:j.mockScore,others:j.others,subjects:j.subjects,owned:j.owned,autoTasks:true}}}
function badge(t,cls=''){return '<span class="chip-s '+cls+'">'+esc(t)+'</span>'}
function itemState(it,today){return it.finished?badge('終わった','ok'):it.locked?badge('講師が調整','wait'):it.hold?badge('保留','late'):it.replaced?badge('手持ちを使う','ok'):it.from>today?badge('これから'):it.to<today?badge('期間が過ぎた','late'):badge('取り組み中','wait')}
function upperSummary(p){const j=p.juken;return card('志望校から逆算した計画','<p><b>'+esc(j.bandName||'')+'</b></p><p>'+esc(j.routeName||'')+'</p>'+(j.gap?'<p>目標との差：'+j.gap.gap+'（'+esc(j.gap.level)+'）</p>'+hint(j.adjustNote):hint('偏差値が分からないため、標準の進め方です。'))+(j.mixedNote?hint(j.mixedNote):'')+(j.ratioNote?hint(j.ratioNote):'')+btn('教材ごとの期間を見る','page','action',{page:'upper'}))}
function dj(x){const m=/^\d{4}-(\d{2})-(\d{2})$/.exec(String(x));return m?Number(m[1])+'月'+Number(m[2])+'日':esc(x)}
function upperView(){
 const p=plan();if(!p||!p.juken)return navBack()+hint('この計画には、受験逆算の上段がありません。');const j=p.juken,teacher=S.role==='teacher',d=doc(),due=C.reviewDue(d,S.date);
 let h=navBack()+'<h1 class="page-title">教材ごとの期間</h1>'+card(p.title,'<p>'+esc(String(j.bandName||'').replace(/（.*?）/g,''))+'</p>'+(j.gap?'<p class="caption">いまの学力：'+(j.gap.level==='ビハインド'?'追い上げが必要':j.gap.level==='リード'?'余裕があります':'標準の進め方')+'</p>':'')+(teacher&&due?'<div class="alert">今月の見直し（月1回）が、まだです。</div>':''));
 (j.materials||[]).forEach((sp,si)=>{
  if(sp.missing){h+=card(sp.subject+'（ルートなし）',hint(sp.note)+(teacher?'<form data-form="jadd"><input type="hidden" name="subject" value="'+esc(sp.subject)+'">'+field('追加する教材名','name','','text','required maxlength="60"')+field('期間（週）','weeks',8,'number','min="1" max="104" required')+'<button class="secondary">教材を追加する</button></form>':hint('講師が、教材を足します。')));return}
  h+=card(sp.subject+' · 全'+sp.totalWeeks+'週',(sp.fits?'':'<div class="alert">入試までに入りきりません（約'+sp.shortDays+'日の超過）。</div>')+(sp.skipped&&sp.skipped.length?hint('見送り：'+sp.skipped.map(x=>x.name+'（'+x.reason+'）').join('、')):'')+sp.items.map((it,i)=>'<div class="uitem"><p><b>'+esc(it.name)+'</b></p><p class="caption">'+itemState(it,S.date)+' '+dj(it.from)+'〜'+dj(it.to)+'（'+it.weeks+'週）'+(it.total?' ・ 進み '+(it.doneUnits||0)+esc(it.unit||'')+' / '+it.total+esc(it.unit||''):'')+'</p>'+(it.replaced?hint('「'+it.replaced.fromName+'」の代わり：'+it.replaced.why):'')+(it.hold?hint('手持ちの「'+it.hold.ownName+'」を使いますか？'):'')+(teacher&&!it.finished?'<details class="more sm" '+(it.hold?'open':'')+'><summary>調整する</summary><form data-form="jweeks" class="inlinefields"><input type="hidden" name="subject" value="'+esc(sp.subject)+'"><input type="hidden" name="index" value="'+i+'">'+field('期間（週）','weeks',it.weeks,'number','min="1" max="104" required')+'<button class="secondary">期間を変える</button></form><div class="actions">'+btn('今回は使わない','jskip','linkbtn',{subject:sp.subject,index:i})+(it.hold?btn('手持ちに置き換える','jaccept','secondary',{subject:sp.subject,index:i})+btn('予定どおりにする','jreject','secondary',{subject:sp.subject,index:i}):'')+'</div></details>':'')+'</div>').join(''));
 });
 if(j.owned&&j.owned.length)h+=card('手持ちの教材の扱い',j.owned.map(o=>'<p><b>'+esc(o.name)+'</b> '+badge(o.status,o.status==='置き換え'?'ok':o.status==='保留'?'late':'wait')+'<br><small>'+esc(o.note)+'</small></p>').join(''));
 if(teacher)h+=card('月1回の見直し','<form data-form="jreview">'+select('新しい模試（任意）','mockType',[['','入れない'],'河合','東進','進研','駿台'],'')+field('偏差値','mockScore','','number','min="20" max="85" step="0.5"')+'<button class="primary">見直しを実行する</button></form>');
 if((j.reviews||[]).length)h+=card('見直しの記録',j.reviews.slice(0,3).map(r=>'<p><b>'+esc(r.at)+'</b>'+(r.level?' · '+esc(r.level):'')+'</p>'+r.changes.map(c=>'<p class="caption">・'+esc(c)+'</p>').join('')+r.warnings.map(c=>'<p class="caption warn">！'+esc(c)+'</p>').join('')).join(''));
 return h;
}
const jukenFormHandlers={
 jweeks:v=>({type:'juken_adjust',planId:plan().id,ops:[{op:'weeks',subject:v.subject,index:Number(v.index),weeks:Number(v.weeks)}]}),
 jadd:v=>({type:'juken_adjust',planId:plan().id,ops:[{op:'add',subject:v.subject,withName:v.name,weeks:Number(v.weeks)}]}),
 jreview:v=>({type:'juken_review',planId:plan().id,mock:v.mockType&&v.mockScore!==''?{type:v.mockType,score:Number(v.mockScore)}:undefined})
};

const TYPE_INFO={test:['定期テスト','テストの日までに、範囲を終わらせる計画です。'],exam:['検定','検定の日までに、勉強を進める計画です。'],juken:['大学受験','志望校から逆算して、教材と期間を決める計画です。'],habit:['習慣づくり','毎日少しずつ、続けるための計画です。'],task:['課題・提出物','提出日までに、課題を終わらせる計画です。']};
function kvr(k,v){return '<div class="kvr"><span>'+k+'</span><b>'+v+'</b></div>'}
function mdw(date){const d=new Date(date+'T00:00:00Z');return (d.getUTCMonth()+1)+'月'+d.getUTCDate()+'日（'+'日月火水木金土'[d.getUTCDay()]+'）'}
function posLabel(t,p){return t.unit==='ページ'?'p.'+p:t.unit==='問題の番号'?'No.'+p:t.unit==='単語の番号'?p+'番':p+'まで'}
function partialLabel(t){return t.unit==='ページ'?'どのページまで？':'何番まで？'}
function rowBtn(title,desc,page){return '<button type="button" class="action" data-action="page" data-page="'+page+'"><span><b>'+esc(title)+'</b></span></button>'}
function noPlan(){return '<h1 class="page-title">計画をつくりましょう</h1><div class="hero"><p>毎日のやることを、自動で決めます。<br>約3分で、つくれます。</p>'+btn('計画をつくる','new','primary')+'</div>'}
function taskCard(t,d,interactive=true){const r=d.records[t.id],amount=t.text.startsWith(t.name)?t.text.slice(t.name.length).trim():t.text;return '<button type="button" class="task '+(r?.mode||'')+'" data-action="editTask" data-id="'+esc(t.id)+'" style="text-align:left"><span class="box2" aria-hidden="true">'+(r?.mode==='done'?'✓':r?.mode==='partial'?'◐':'')+'</span><span class="task-title"><span class="t1">'+esc(t.date.slice(5).replace('-','/'))+' ・ '+esc(t.subject)+'</span><span class="t2">'+esc(t.name)+'</span><span class="t3">'+esc(amount)+' ・ '+t.minutes+'分</span></span></button>'}
function taskRow(t,d){const r=d.records[t.id],open=S.openTask===t.id,future=t.date>S.date,mark=r?.mode==='done'?'✓':r?.mode==='partial'?'◐':r?.mode==='none'?'−':'',status=r?(r.mode==='done'?'できた':r.mode==='none'?'やらなかった':'途中まで（'+esc(posLabel(t,r.position))+'）'):'',amount=t.text.startsWith(t.name)?t.text.slice(t.name.length).trim():t.text;
 const manual=t.from==null&&plan().type!=='habit',panel=open?'<div class="taskpanel">'+(future?'<p class="q">この日は、まだ記録できません</p>':'<p class="q">どこまでできた？</p><div class="three">'+btn('全部できた','reportDone',S.partialOpen||S.carryMode?'secondary':'primary')+(manual?btn('途中まで','carryAsk','secondary',{mode:'partial'})+btn('やらなかった','carryAsk','secondary',{mode:'none'}):btn('途中まで','showPartial','secondary')+btn('やらなかった','reportNone','secondary'))+'</div>'+(S.carryMode&&manual?'<p class="q">残りは、どうしますか？</p><div class="three">'+btn('明日にやる','carryYes','primary')+btn('やらない','carryNo','secondary')+'</div>':'')+(S.partialOpen?'<form data-form="partial">'+field(partialLabel(t),'position',r?.position??'','number','required inputmode="numeric" placeholder="例：'+Math.round(((t.from??1)+(t.to??10))/2)+'" min="'+(t.from??0)+'" max="'+(t.to??180)+'"')+'<button class="primary">記録する</button></form>':''))+'</div>':'';
 return '<div class="taskwrap"><div class="task '+(r?.mode||'')+'"><span class="box2" aria-hidden="true">'+mark+'</span><span class="task-title"><span class="t1">'+esc(t.subject)+'</span><span class="t2">'+esc(t.name)+'</span><span class="t3">'+esc(amount)+' ・ '+t.minutes+'分</span>'+(status?'<span class="t4">'+status+'</span>':'')+'</span>'+(!r&&!future&&!open?'<button type="button" class="rec ok" data-action="quickDone" data-id="'+esc(t.id)+'">できた</button><button type="button" class="rec" data-action="openTask" data-id="'+esc(t.id)+'" aria-label="途中まで・やらなかった">途中まで</button>':'<button type="button" class="rec" data-action="openTask" data-id="'+esc(t.id)+'" aria-expanded="'+open+'">'+(open?'閉じる':r?'直す':'記録する')+'</button>')+'</div>'+panel+'</div>'}
function todayView(){const d=doc(),p=C.active(d);if(!p)return noPlan();
 const date=S.selectedDate||S.date,isToday=date===S.date,st=C.stateOf(p,S.date),pr=C.progress(d,S.date),tasks=p.tasks.filter(t=>t.date===date).sort((a,b)=>a.id<b.id?-1:a.id>b.id?1:0),done=tasks.filter(t=>d.records[t.id]).length,monday=C.week(date),future=date>S.date,tm=d.records['time:'+date]?.minutes;
 let h='<h1 class="page-title">'+(isToday?'今日やること':esc(mdw(date))+'のやること')+'</h1><p class="subtle">'+esc(p.title)+'</p>';
 if(st.phase==='after')h+='<div class="notice">この計画は、終わりました。</div>'+btn('新しい計画をつくる','new','primary');
 else if(st.phase==='before')h+='<div class="notice">'+esc(mdw(p.start))+'から始まります。</div>';
 if(pr&&pr.needsReplan&&st.phase==='during')h+='<div class="alert"><b>遅れがあります</b>（'+pr.missedCount+'件）'+(pr.fits?'':'<br>このままだと、期間内に終わりません。')+'</div>'+btn('遅れを組み直す','replan','primary');
 h+='<div class="strip" role="group" aria-label="日付を選ぶ">'+Array.from({length:7},(_,i)=>{const dt=C.add(monday,i);return '<button type="button" data-action="date" data-date="'+dt+'" class="'+(dt===date?'sel':'')+'" '+(dt===S.date?'aria-current="date"':'')+'>'+'月火水木金土日'[i]+'<b>'+Number(dt.slice(8))+'</b><small>'+(dt===S.date?'今日':'')+'</small></button>'}).join('')+'</div>';
 if(!tasks.length)h+='<div class="empty">この日の予定は、ありません。</div>';
 else h+='<p class="progress-label"><span><b>'+done+' / '+tasks.length+'</b> 完了</span></p>'+tasks.map(t=>taskRow(t,d)).join('');
 if(!future&&(done>0||!tasks.length))h+=card(isToday?'今日の勉強時間':'この日の勉強時間','<div class="chips">'+[30,60,90,120,180].map(m=>'<button type="button" data-action="studyChip" data-m="'+m+'" class="'+(tm===m?'sel':'')+'">'+(m<60?m+'分':m%60?Math.floor(m/60)+'時間'+(m%60)+'分':m/60+'時間')+'</button>').join('')+'</div><form data-form="studyMin" class="inlinefields search">'+field('分で入れる','minutes',(tm!=null&&![30,60,90,120,180].includes(tm))?tm:'','number','min="0" max="1440" required inputmode="numeric" placeholder="例：45"')+'<button class="secondary">記録</button></form>');
 if(d.feedback.length)h+=card('講師からのひとこと','<p>'+esc(d.feedback[0].text)+'</p><p class="caption">'+esc(d.feedback[0].at.slice(0,10))+'</p>');
 return h}
function planView(){const d=doc(),p=plan();if(!p)return noPlan();const g=C.progress(d,S.date),st=C.stateOf(p,S.date),f=v=>v==null?'—':v+'%',teacher=S.role==='teacher',paused=p.status==='paused',started=Object.keys(d.records).some(k=>k.indexOf('time:')!==0);
 const sorted=p.tasks.slice().sort((a,b)=>a.date.localeCompare(b.date)||(a.id<b.id?-1:1)),weeks={};sorted.forEach(t=>{(weeks[C.week(t.date)]=weeks[C.week(t.date)]||[]).push(t)});
 let h=(teacher?navBack('detail'):'')+'<h1 class="page-title">計画</h1>';
 if(d.plans.length>1)h+='<div class="plans" role="group" aria-label="計画を切り替える">'+d.plans.map(q=>btn(q.title+(q.status==='paused'?'（停止中）':''),'pickPlan',q.id===p.id?'sel':'',{id:q.id})).join('')+'</div>';
 h+='<div class="hero">'+(paused?'<div><span class="planbadge paused">一時停止中</span></div>':st&&st.phase==='after'?'<div><span class="planbadge paused">終わりました</span></div>':'')+'<h2>'+esc(p.title)+'</h2><div class="kv"><span>期間</span><b>'+esc(mdw(p.start))+'〜'+esc(mdw(p.goal))+'</b></div>'+(p.target?'<div class="kv"><span>目標</span><b>'+esc(p.target)+'</b></div>':'')+(st&&st.phase==='during'?'<div class="kv"><span>終わりまで</span><b>あと'+st.daysLeft+'日</b></div>':'')+(g&&!paused?(started?'<div><div class="progress-label"><span>今週の進み</span><strong>'+f(g.achievement.thisWeek)+'</strong></div>'+progress(g.achievement.thisWeek||0)+(g.achievement.lastWeek!=null?'<p class="caption">先週 '+f(g.achievement.lastWeek)+(g.streak>1?' ・ '+g.streak+'日連続':'')+'</p>':'')+'</div>':'<p class="caption">まず、今日の1つを終わらせましょう。</p>'):'')+'</div>';
 if(paused)h+='<div class="notice">いまは、一時停止中です。</div>'+btn('この計画を再開する','activate','primary',{id:p.id});
 if(p.leftovers.length)h+='<div class="alert"><b>期間内に終わらない範囲があります</b><br>'+p.leftovers.map(l=>esc(l.text)).join('<br>')+'</div>';
 if(p.juken)h+=upperSummary(p);
 if(p.roadmap&&p.roadmap.length||p.type==='juken'&&teacher)h+=card('月ごとの道筋',(p.roadmap||[]).map(m=>'<p><b>'+esc(m.month)+'</b><br>'+esc(m.text)+'</p>').join('')||'<p class="caption">まだ、ありません。</p>')+(teacher?btn('月ごとの道筋を書く','page','secondary',{page:'roadmap'}):'');
 h+='<div class="rows">'+rowBtn('計画を直す','','edit')+rowBtn('通知の設定','',teacher?'teacherSettings':'settings')+'</div><details class="more sm"><summary>そのほか</summary><div class="rows">'+rowBtn('PDFで保存','','pdf')+rowBtn('変更の履歴','','history')+'<button type="button" class="action" data-action="new"><span><b>新しい計画をつくる</b></span></button></div></details>';
 return h+'<details class="sched"><summary>予定をすべて見る（'+p.tasks.length+'件）</summary>'+Object.entries(weeks).map(([wk,ts])=>'<div class="wk"><h4>'+esc(mdw(wk))+'の週</h4>'+ts.map(t=>'<button type="button" class="row" data-action="editTask" data-id="'+esc(t.id)+'"><span class="d">'+esc(t.date.slice(5).replace('-','/'))+'</span><span>'+esc(t.text)+'</span><span class="m">'+(d.records[t.id]?esc(modeLabel(d.records[t.id]).split(' · ')[0]):'')+'</span></button>').join('')+'</div>').join('')+'</details>'}
function studentsView(){const rows=S.students.map(x=>({s:x,m:C.studentSummary(x.doc,S.date)})).sort((a,b)=>((b.m.missedCount>0)-(a.m.missedCount>0))||((a.m.checkedThisWeek?1:0)-(b.m.checkedThisWeek?1:0))),wait=rows.filter(r=>!r.m.checkedThisWeek).length;
 return '<h1 class="page-title">担当の生徒</h1><p class="subtle">確認待ち：<b>'+wait+'人</b></p>'+(rows.length?rows.map(({s,m})=>'<button type="button" class="stu" data-action="student" data-id="'+esc(s.studentId)+'"><div class="h"><b>'+esc(s.name)+'</b><span class="chip-s '+(m.checkedThisWeek?'ok':'wait')+'">'+(m.checkedThisWeek?'確認ずみ':'確認待ち')+'</span></div><p class="caption">'+(m.hasPlan?esc(m.title):'計画が、まだありません')+'</p>'+(m.hasPlan?(m.lastRecord?progress(m.thisWeek||0)+'<p class="caption">今週の進み '+(m.thisWeek==null?'—':m.thisWeek+'%')+' ・ 最後の記録 '+esc(m.lastRecord.slice(5).replace('-','/'))+(m.missedCount?' ・ <span class="warn">遅れ '+m.missedCount+'件</span>':''):'<p class="caption">まだ記録がありません')+'</p>':'')+'</button>').join(''):'<div class="empty">担当の生徒は、まだいません。</div>')}
function detailView(){const d=doc(),p=C.active(d),m=C.studentSummary(d,S.date),f=v=>v==null?'—':v+'%',recs=(p?.tasks||[]).filter(t=>d.records[t.id]).slice(-5).reverse();
 return navBack('students')+'<h1 class="page-title">'+esc(item().name)+'</h1><p class="subtle">'+(p?esc(p.title):'計画が、まだありません')+'</p>'+(p?(m.lastRecord?card('今週の進み','<div class="progress-label"><span></span><strong>'+f(m.thisWeek)+'</strong></div>'+progress(m.thisWeek||0)+'<p class="caption">'+(m.lastWeek!=null?'先週 '+f(m.lastWeek)+' ・ ':'')+'遅れ '+m.missedCount+'件 ・ 最後の記録 '+esc(m.lastRecord.slice(5).replace('-','/'))+'</p>')+card('最近の記録',recs.map(t=>'<p><b>'+esc(t.name)+'</b><br><span class="caption">'+esc(modeLabel(d.records[t.id]))+'</span></p>').join('')):'<div class="empty">まだ記録がありません。</div>'):'')+(m.checkedThisWeek?'<div class="notice">今週は、確認ずみです。</div>':m.lastRecord?btn('確認ずみにする','check','primary'):'')+'<div class="rows">'+rowBtn('メッセージを送る','','feedback')+(p?rowBtn('計画を見る','','plan')+rowBtn('計画を直す','','edit'):'')+'</div>'+btn('変更の履歴','page','linkbtn',{page:'history'})+btn('＋ 新しい計画をつくる','new','secondary')}
function roadmapView(){const p=plan();if(!p)return noPlan();return navBack()+card('対象：'+item().name+' · '+p.title,hint('1行に1か月。例：2026-11 | 英単語を仕上げる。自動のAI提案ではなく講師の方針を保存します。'))+'<form data-form="roadmap"><label class="field">月ごとの道筋<textarea name="months" rows="9">'+esc((p.roadmap||[]).map(m=>m.month+' | '+m.text).join('\n'))+'</textarea></label><button class="primary">道筋を保存する</button></form>'}
function feedbackView(){return navBack('detail')+'<h1 class="page-title">ひとことを送る</h1><p class="subtle">'+esc(item().name)+'さんに、届きます。</p>'+(doc().feedback.length?card('これまでに、送ったもの',doc().feedback.slice(0,2).map(f=>'<p>'+esc(f.text)+'</p><p class="caption">'+esc(f.at.slice(0,10))+'</p>').join('')):'')+'<form data-form="feedback" class="inputcard"><label class="field">メッセージ<textarea name="text" maxlength="1000" required placeholder="例：英単語は、順調です。数学は、例題から先にやってみましょう。"></textarea></label><button class="primary">このメッセージを送る</button></form>'}
