function settingsView(){const n=doc().settings;return navBack('plan')+'<h1 class="page-title">通知の設定</h1><form data-form="settings" class="inputcard">'+card('毎日のお知らせ',field('時刻','todo',n.todo,'time','required')+'<label class="checkrow"><input type="checkbox" name="same" '+(n.same?'checked':'')+'> 記録のお願いも、同じ時刻に送る</label>'+'<div class="rep" '+(n.same?'hidden':'')+'>'+field('記録のお願いの時刻','report',n.report,'time','required '+(n.same?'disabled':''))+'</div>')+card('毎週の見直しのお知らせ','<div class="inlinefields">'+select('曜日','wd',['日','月','火','水','木','金','土'].map((d,i)=>[i,d]),n.wd)+field('時刻','wt',n.wt,'time','required')+'</div>')+(item().relation!==undefined?card('通知を受け取る人',select('受け取る人','notifyTo',[['auto','自動（本人→母→父）'],['self','本人'],['mother','母'],['father','父'],['all','全員']],n.notifyTo||'auto')):'')+'<div class="wizbar one savebar"><button class="primary">保存する</button></div></form>'}
