function editView(){const p=plan();if(!p)return noPlan();return navBack(S.role==='teacher'?'detail':'plan')+'<h1 class="page-title">計画を直す</h1><p class="subtle">'+esc(p.title)+'</p><div class="rows">'+rowBtn('今日は休む・別の日に回す','','skip')+'<button type="button" class="action" data-action="rebuild"><span><b>条件を変えて、つくり直す</b></span></button><button type="button" class="action" data-action="addTask"><span><b>やることを1つ足す</b></span></button></div><details class="more"><summary>予定を個別に直す（'+p.tasks.length+'件）</summary>'+p.tasks.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(t=>taskCard(t,doc(),false)).join('')+'</details>'}
function editingTask(){return plan()?.tasks.find(t=>t.id===S.taskId)}
function reportView(){const t=editingTask();if(!t)return navBack('today');if(t.date>S.date)return navBack('today')+hint('未来の日の実績はまだ記録できません。');const r=doc().records[t.id];return navBack('today')+card(t.name,'<p>'+esc(t.text)+'</p><p>記録：'+esc(modeLabel(r))+'</p>')+btn('予定の範囲が終わった','reportDone','primary')+'<form data-form="partial">'+field(t.from==null?'学習した分数・到達位置':'どの番号・ページまで終わりましたか？','position',r?.position??t.from??0,'number','required min="'+(t.from??0)+'" max="'+(t.to??180)+'"')+'<button class="secondary">途中までとして記録する</button></form>'+btn('取り組まなかった','reportNone','secondary')+hint('押し直すと、この予定の記録を更新します。')}
function editTaskView(){const t=editingTask();if(t&&doc().records[t.id])return navBack('plan')+card(t.name,'<p>'+esc(t.text)+'</p><p>'+esc(modeLabel(doc().records[t.id]))+'</p>')+hint('記録済みの予定は変更できません。記録は今日の画面から修正できます。');const p=plan();if(!p)return noPlan();
 const num=t&&t.from!=null&&!t.item,auto=t&&t.item;
 const head=navBack('edit')+'<h1 class="page-title">'+(t?'予定を直す':'やることを足す')+'</h1>'+(t?'<p class="subtle">'+esc(t.name)+'</p>':'');
 if(num){const rest=p.tasks.filter(x=>x.name===t.name&&x.from!=null&&!x.item&&!doc().records[x.id]&&x.date>=S.date).reduce((m,x)=>Math.max(m,x.to),t.to);return head+'<form data-form="editTask" class="inputcard">'+field('取り組む日','date',t.date,'date','min="'+S.date+'" max="'+p.goal+'" required')+'<div class="kvr"><span>始まり</span><b>'+esc(t.from)+'（自動）</b></div>'+field('どこまでやる？（終わりの番号）','to',t.to,'number','min="'+t.from+'" max="'+rest+'" required inputmode="numeric"')+'<p class="caption">目安：約<b id="estMin">'+t.minutes+'</b>分（<span id="estAmt">'+(t.to-t.from+1)+'</span>'+esc(t.unit==='ページ'?'ページ':t.unit==='問題の番号'?'問':'語')+'）。終わりの番号を変えると、同じ教材の残りの予定も、自動で並び直ります。</p><button class="primary">変更を保存する</button></form>'+btn('この予定を削除する','deleteTask','secondary danger')}
 if(auto)return head+'<form data-form="editTask" class="inputcard"><p>'+esc(t.text)+'（'+t.minutes+'分）</p>'+field('取り組む日','date',t.date,'date','min="'+S.date+'" max="'+p.goal+'" required')+'<button class="primary">変更を保存する</button></form>'+btn('この予定を削除する','deleteTask','secondary danger');
 if(!t){const pn=p.type!=='habit';return head+'<form data-form="editTask" class="inputcard">'+field('名前','name','','text','required maxlength="120" placeholder="例：英単語、プリント"')+field('科目','subject','学習')+(pn?select('数え方','unit',[['ページ','ページ'],['問題の番号','問題の番号'],['単語の番号','単語の番号'],['','番号なし（文章で書く）']],'ページ'):'')+field('取り組む日','date',S.date,'date','min="'+S.date+'" max="'+p.goal+'" required')+(pn?'<div class="k-num"><div class="inlinefields">'+field('はじめ','from',1,'number','min="1" max="100000" required inputmode="numeric"')+field('おわり','to',10,'number','min="1" max="100000" required inputmode="numeric"')+'</div><p class="caption">目安：約<b id="addMin">80</b>分（自動）</p><details class="more sm"><summary>1ページの時間を変える</summary>'+field('1ページ（1問・10単語）にかかる時間（分）','unitMinutes',5,'number','min="1" max="60" required inputmode="numeric"')+'</details></div>':'')+'<div class="k-txt" '+(pn?'hidden':'')+'>'+field('やること','text','','text','maxlength="200" '+(pn?'disabled':'required'))+field('時間（分）','minutes',30,'number','min="1" max="360" inputmode="numeric" '+(pn?'disabled':'required'))+'</div><button class="primary">やることを足す</button></form>'}
 return head+'<form data-form="editTask" class="inputcard">'+field('やること','text',t.text,'text','required maxlength="200"')+field('取り組む日','date',t.date,'date','min="'+S.date+'" max="'+p.goal+'" required')+field('時間（分）','minutes',t.minutes,'number','min="1" max="360" required inputmode="numeric"')+'<button class="primary">変更を保存する</button></form>'+btn('この予定を削除する','deleteTask','secondary danger')}
function skipView(){const p=plan();if(!p)return noPlan();const tasks=p.tasks.filter(t=>t.date===S.date&&!doc().records[t.id]);return navBack(S.role==='teacher'?'edit':'today')+'<h1 class="page-title">今日は休む・別の日に回す</h1><p class="subtle">今日の、まだ記録していない予定を、別の日に移します。</p>'+card('移す予定（今日）',tasks.map(t=>'<p>'+esc(t.text)+'</p>').join('')||'<p class="caption">移せる予定は、ありません。</p>')+'<form data-form="moveDay" class="inputcard">'+field('移す日','date',C.add(S.date,1),'date','min="'+C.add(S.date,1)+'" max="'+p.goal+'" required')+hint('移した日の予定が、そのぶん、増えます。')+'<button class="primary" '+(!tasks.length?'disabled':'')+'>この日に、移す</button></form>'}
function inLineClient(){return typeof liff!=='undefined'&&typeof liff.isInClient==='function'&&liff.isInClient()}
function currentPdf(){return S.pdf&&S.pdf.planId===plan()?.id&&S.pdf.studentId===item()?.studentId&&S.pdf.revision===item()?.revision?S.pdf:null}
function canSharePdf(pdf){try{return !!(pdf&&navigator.share&&navigator.canShare&&navigator.canShare({files:[pdf.file]}))}catch{return false}}

function preparePdfData(response){
 if(typeof response.base64!=='string'||!response.base64.length)throw Error('PDFデータを取得できませんでした。もう一度準備してください');
 let raw;try{raw=atob(response.base64)}catch{throw Error('PDFデータを読み込めませんでした。もう一度準備してください')}
 if(!raw.startsWith('%PDF-'))throw Error('PDF形式のデータを取得できませんでした。もう一度準備してください');
 const file=new File([Uint8Array.from(raw,c=>c.charCodeAt(0))],'学習計画.pdf',{type:'application/pdf'});
 return {file,url:URL.createObjectURL(file),planId:plan().id,studentId:item().studentId,revision:item().revision};
}
function pdfView(){const p=plan();if(!p)return noPlan();const pdf=currentPdf(),line=inLineClient(),sharing=canSharePdf(pdf)&&!pdf?.shareFailed;let controls='';
 if(demo)controls=btn('印刷してPDFで保存','downloadPdf','primary');
 else if(pdf){
  controls=card('PDFの準備ができました','<p>学習計画.pdf · '+Math.max(1,Math.round(pdf.file.size/1024))+' KB</p>'+hint('下のプレビューで内容を確認して、保存ボタンを押してください。'));
  if(sharing)controls+=btn('PDFを「ファイル」に保存','sharePdf','primary')+hint('開いたメニューで「“ファイル”に保存」を選んでください。');
  else if(line)controls+=hint('この画面で保存メニューを使えないため、PDF画面から保存してください。');
  controls+='<iframe class="pdf-preview" src="'+esc(pdf.url)+'" title="学習計画PDFのプレビュー" style="display:block;width:100%;height:390px;border:1px solid var(--line);border-radius:12px;background:white"></iframe>';
  if(line&&!sharing)controls+='<a class="primary" id="pdfOpenLink" href="'+esc(pdf.url)+'" target="_blank" rel="noopener">PDFを開く</a>';
  if(!line)controls+='<a class="'+(sharing?'secondary':'primary')+'" id="pdfDownloadLink" href="'+esc(pdf.url)+'" download="学習計画.pdf" target="_blank" rel="noopener">PDFをダウンロード</a>';
 }else controls=hint('PDFを準備すると、内容の確認と保存ができます。')+btn('PDFを準備する','downloadPdf','primary');
 return navBack()+card(p.title,'<p>'+esc(p.start)+'〜'+esc(p.goal)+'</p>')+controls;
}

window.addEventListener('pagehide',e=>{if(!e.persisted&&S.pdf){URL.revokeObjectURL(S.pdf.url);S.pdf=null}});

function wizardView(){
 const prev=C.active(doc()),w=S.wizard;if(!w)return noPlan();if(w.input.type==='juken'&&!wizardSteps(w.input).includes(w.step))w.step=3;
 const a=w.input,n=w.step,steps=wizardSteps(a),idx=steps.indexOf(n)+1,total=steps.length;
 const q=['どんな計画？','名前と目標','いつからいつまで？',a.type==='juken'?'志望校と、今の学力':'何を、どこまで？','勉強できる時間','この内容で作成しますか？'];
 const help=[];
 const days=['月','火','水','木','金','土','日'],opts=[[0,'休む'],[30,'30分'],[60,'1時間'],[90,'1時間半'],[120,'2時間'],[180,'3時間']];
 let body='';
 if(n===0)body=(prev?'<div class="notice">前回の計画：<b>'+esc(prev.title)+'</b>（'+pct(prev,doc())+'%）。続きから、新しい計画をつくれます。</div>':'')+'<div class="inputcard">'+Object.entries(C.TYPES).map(([k,label])=>'<label class="opt"><input type="radio" name="type" value="'+k+'" '+(a.type===k?'checked':'')+'><span><b>'+esc(TYPE_INFO[k]?TYPE_INFO[k][0]:label)+'</b><small>'+esc(TYPE_INFO[k]?TYPE_INFO[k][1]:'')+'</small></span></label>').join('')+'</div>';
 if(n===1)body=field('計画の名前','title',a.title,'text','required maxlength="120" placeholder="例：期末テスト"')+field('目標（なくてもOK）','target',a.target,'text','maxlength="200" placeholder="例：数学70点"');
 if(n===2)body='<div class="inlinefields">'+field('いつから','start',a.start,'date','min="'+S.date+'" required')+field('いつまで','goal',a.goal,'date','min="'+a.start+'" required')+'</div>';
 if(n===3&&a.type==='juken')body=jukenStep(w);
 if(n===3&&a.type!=='juken')body=a.materials.map((m,i)=>'<div class="material"><h3>教材 '+(i+1)+'</h3>'+field('教材の名前','m'+i+'_name',m.name,'text','required maxlength="120" placeholder="例：学校の数学ワーク"')+'<div class="inlinefields">'+field('はじめ（'+({'ページ':'ページ','問題の番号':'問題番号','単語の番号':'単語番号'}[m.unit]||'ページ')+'）','m'+i+'_from',m.from,'number','min="1" max="100000" required inputmode="numeric"')+field('おわり（'+({'ページ':'ページ','問題の番号':'問題番号','単語の番号':'単語番号'}[m.unit]||'ページ')+'）','m'+i+'_to',m.to,'number','min="1" max="100000" required inputmode="numeric"')+'</div><details class="more sm"><summary>科目・単位・時間を変える</summary>'+field('科目','m'+i+'_subject',m.subject)+select('数え方','m'+i+'_unit',['ページ','問題の番号','単語の番号'],m.unit)+field(m.unit==='単語の番号'?'10単語の時間（分）':'1ページ・1問の時間（分）','m'+i+'_minutes',m.minutes,'number','min="1" max="60" required inputmode="numeric"')+'</details>'+(a.materials.length>1?btn('この教材を外す','removeMaterial','secondary',{index:i}):'')+'</div>').join('')+(a.materials.length<10?btn('＋ 教材を足す','addMaterial','secondary'):'');
 if(n===4)body='<div class="inlinefields">'+select('平日（月〜金）','wk',opts,a.availability[0])+select('土日','we',opts,a.availability[5])+'</div><details class="more sm"><summary>曜日ごとに変える</summary><div class="inlinefields">'+days.map((d,i)=>select(d+'曜日','day'+i,opts,a.availability[i])).join('')+'</div></details><details class="more sm"><summary>課題・予備日・行事を入れる</summary>'+select('学校の課題（1週間）','hwWeekly',['ほとんどない','1〜2時間','3〜4時間','5時間以上'],a.hwWeekly||'ほとんどない')+select('予備日','reserveDay',[['','決めない'],...days.map(d=>[d,d+'曜日'])],a.reserveDay||'')+'<p class="q">勉強できない日</p>'+(a.busyDates||[]).map((b,i)=>'<div class="inlinefields">'+field('いつから','bf'+i,b.from,'date','min="'+a.start+'" max="'+a.goal+'"')+field('いつまで（1日だけなら空）','bt'+i,b.to||'','date','min="'+a.start+'" max="'+a.goal+'"')+'</div>'+btn('この日を外す','removeBusy','linkbtn',{i})).join('')+((a.busyDates||[]).length<8?btn('＋ 勉強できない日を足す','addBusy','secondary'):'')+'</details>';
 if(n===5)body='<div class="card">'+kvr('名前',esc(a.type==='juken'?jukenInput(a).title:a.title))+kvr('種類',esc(TYPE_INFO[a.type]?TYPE_INFO[a.type][0]:C.TYPES[a.type]))+(a.type==='juken'?'':(a.target?kvr('目標',esc(a.target)):'')+kvr('期間',esc(mdw(a.start))+'〜'+esc(mdw(a.goal))))+(a.type==='juken'?jukenSummary(a):a._skipMat?kvr('教材','残りの範囲（自動）'):a.materials.map((m,i)=>kvr(a.materials.length>1?'教材'+(i+1):'教材',esc(m.name)+'<br><span class="caption">'+(m.unit==='ページ'?'p.':'')+m.from+'〜'+m.to+(m.unit==='問題の番号'||m.unit==='単語の番号'?'番':'')+'</span>')).join(''))+kvr('1日の時間','平日 '+(a.availability[0]?a.availability[0]+'分':'休み')+' ・ 土日 '+(a.availability[5]?a.availability[5]+'分':'休み'))+'</div>'+(w.rebuildId?'<div class="notice">今日以降の予定を、つくり直します。</div>':(prev?'<div class="notice">いまの計画は、一時停止します。</div>':''));
 return '<form id="wizardForm" data-form="wizard" class="inputcard" novalidate><div class="chat-progress"><span>'+(n===5?'確認':idx+' / '+(total-1))+'</span>'+progress(Math.round(idx/total*100))+'</div><h1 class="wizq">'+q[n]+'</h1>'+(S.students.length>1||S.role==='teacher'?'<p class="subtle">'+esc(item().name)+'さん</p>':'')+body+'<div class="wizbar'+(idx>1?'':' one')+'">'+(idx>1?btn('戻る','wizardBack','secondary'):'')+'<button class="primary">'+(n===5?'この内容で作成する':'次へ')+'</button></div>'+btn('あとで続ける','interrupt','linkbtn')+'</form>'}
function addEst(){const f=document.querySelector('form[data-form=editTask]'),m=$('addMin');if(!f||!m||S.taskId)return;const g=n=>Number((f.querySelector('[name='+n+']')||{}).value),u=(f.querySelector('[name=unit]')||{}).value,fr=g('from'),to=g('to'),um=g('unitMinutes')||5;m.textContent=to>=fr&&fr>0?Math.max(1,Math.ceil((to-fr+1)/(u==='単語の番号'?10:1))*Math.ceil(um*1.5)):'—'}
function captureWizard(){const f=$('wizardForm');if(!f||!S.wizard)return;const data=new FormData(f),a=S.wizard.input,n=S.wizard.step;if(n===0)a.type=data.get('type');if(n===1){a.title=data.get('title');a.target=data.get('target')}if(n===2){a.start=data.get('start');a.goal=data.get('goal')}if(n===3&&a.type==='juken')jukenCapture(data,S.wizard);
 if(n===3&&a.type!=='juken')a.materials=a.materials.map((m,i)=>({name:data.get('m'+i+'_name'),subject:data.get('m'+i+'_subject'),unit:data.get('m'+i+'_unit'),from:Number(data.get('m'+i+'_from')),to:Number(data.get('m'+i+'_to')),minutes:Number(data.get('m'+i+'_minutes'))}));if(n===4){a.availability=a.availability.map((_,i)=>Number(data.get('day'+i)));a.hwWeekly=data.get('hwWeekly');a.reserveDay=data.get('reserveDay');a.busyDates=(a.busyDates||[]).map((_,i)=>({from:data.get('bf'+i)||'',to:data.get('bt'+i)||''}))}saveDraft()}
function printHtml(p){return '<!doctype html><html lang="ja"><meta charset="utf-8"><title>'+esc(p.title)+'</title><style>body{font-family:sans-serif;color:#272d30;padding:20px}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ccc;padding:10px;font-size:12px;text-align:left}h1{font-size:22px}@page{size:A4;margin:12mm}</style><h1>'+esc(p.title)+'</h1><p>'+esc(item().name)+' · '+esc(p.start)+'〜'+esc(p.goal)+'</p><p>'+esc(p.target)+'</p><table><thead><tr><th>日付</th><th>やること</th><th>目安</th></tr></thead><tbody>'+p.tasks.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(t=>'<tr><td>'+esc(t.date)+'</td><td>'+esc(t.text)+'</td><td>'+t.minutes+'分</td></tr>').join('')+'</tbody></table>'+(p.leftovers.length?'<h2>入りきらなかった範囲</h2>'+p.leftovers.map(l=>'<p>'+esc(l.text)+'</p>').join(''):'')+'</html>'}
$('phone').addEventListener('change',e=>{if(e.target.name==='unit'&&S.page==='editTask'){const num=e.target.value!=='',f=e.target.form,k=f.querySelector('.k-num'),x=f.querySelector('.k-txt');if(k){k.hidden=!num;k.querySelectorAll('input').forEach(i=>i.disabled=!num)}if(x){x.hidden=num;x.querySelectorAll('input').forEach(i=>i.disabled=num)}addEst()}if(e.target.name==='wk'||e.target.name==='we'){const idx=e.target.name==='wk'?[0,1,2,3,4]:[5,6];idx.forEach(i=>{const el=$('content').querySelector('[name=day'+i+']');if(el)el.value=e.target.value})}saveFormDraft(e);if(e.target.name==='same'){const report=$('content').querySelector('[name=report]');if(report){report.disabled=e.target.checked;const w=report.closest('.rep');if(w)w.hidden=e.target.checked}}if(S.page==='wizard')captureWizard()});
$('phone').addEventListener('input',e=>{if(S.page==='wizard')captureWizard();else saveFormDraft(e);if(S.page==='editTask'&&!S.taskId&&['from','to','unitMinutes'].includes(e.target.name))addEst();if(S.page==='editTask'&&e.target.name==='to'){const t=editingTask(),n=Number(e.target.value);if(t&&t.from!=null&&n>=t.from){const m=$('estMin'),c=$('estAmt');if(m)m.textContent=C.estimate(plan(),t,t.from,n);if(c)c.textContent=n-t.from+1}}});
$('phone').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||S.busy)return;const a=b.dataset.action;const navigate=page=>{if(page==='today')S.planId=doc().activeId;S.page=page;S.error='';render();$('content').scrollTop=0};
 if(a==='page')return navigate(b.dataset.page);if(a==='pickStudent'){S.studentId=b.dataset.id;S.planId=null;S.selectedDate=S.date;S.wizard=null;return navigate('today')}if(a==='refresh')return busy(boot,'最新の状態に更新しました');if(a==='student'){S.studentId=b.dataset.id;S.planId=null;return navigate('detail')}if(a==='date'){S.selectedDate=b.dataset.date;return navigate('today')}if(a==='pickPlan'){S.planId=b.dataset.id;return navigate('plan')}
 if(a==='new'){const saved=localStorage.getItem(draftKey());S.wizard=saved?JSON.parse(saved):newDraft();return navigate('wizard')}
 if(a==='rebuild'){const pl=plan(),hasRec=!pl.juken&&pl.tasks.some(t=>t.date<S.date||doc().records[t.id]);S.wizard={step:1,input:C.copy(pl.input),rebuildId:pl.id};S.wizard.input.start=S.date;S.wizard.input.busyDates=S.wizard.input.busyDates||[];if(hasRec)S.wizard.input._skipMat=true;else delete S.wizard.input._skipMat;return navigate('wizard')}
 if(a==='wizardBack'){captureWizard();S.wizard.step=nextStep(S.wizard,-1);return navigate('wizard')}
 if(a==='interrupt'){captureWizard();return navigate(S.role==='teacher'?'detail':'plan')}
 if(a==='addMaterial'){captureWizard();S.wizard.input.materials.push({name:'',subject:'学習',from:1,to:20,unit:'ページ',minutes:10});return navigate('wizard')}
 if(a==='addBusy'){captureWizard();const l=S.wizard.input.busyDates=S.wizard.input.busyDates||[];l.push({from:'',to:''});return navigate('wizard')}
 if(a==='removeBusy'){captureWizard();S.wizard.input.busyDates.splice(Number(b.dataset.i),1);return navigate('wizard')}
 if(a==='removeMaterial'){captureWizard();S.wizard.input.materials.splice(Number(b.dataset.index),1);return navigate('wizard')}
 if(a==='report'||a==='editTask'){S.taskId=b.dataset.id;return navigate(a==='report'?'report':'editTask')}
 if(a==='addTask'){S.taskId=null;return navigate('editTask')}
 if(a==='activate'){if(!confirm('現在の計画を一時停止して、この計画を再開しますか？未記録の予定と終了日は停止期間分だけ後ろにずらします。'))return;return busy(async()=>{await mutate({type:'activate',planId:b.dataset.id});S.page='plan'})}
 if(a==='searchUniv'){captureWizard();const w=S.wizard;w.univResults=window.JukenUniv?JC.search(window.JukenUniv,w.univq,8):[];return navigate('wizard')}
 if(a==='pickUniv'||a==='pickOther'){captureWizard();const w=S.wizard,r=w.univResults[Number(b.dataset.i)],j=w.input.juken;if(!r)return;if(a==='pickUniv'){j.univ=r.univ+' '+r.dept;j.band=r.band;j.dev=r.dev;j.aff=r.aff}else if(j.others.length<3&&!j.others.includes(r.band)||j.others.length<3){j.others.push(r.band);j.othersNames.push(r.univ+' '+r.dept)}w.univResults=[];w.univq='';return navigate('wizard')}
 if(a==='removeOther'){captureWizard();const j=S.wizard.input.juken;j.others.splice(Number(b.dataset.i),1);j.othersNames.splice(Number(b.dataset.i),1);return navigate('wizard')}
 if(a==='searchOwn'){captureWizard();const w=S.wizard,qs=(w.ownq||'').replace(/[\s　]/g,'').toLowerCase(),cat=window.JukenRoute?window.JukenRoute.materials:{};w.ownResults=qs?Object.entries(cat).filter(([id,m])=>m[0].replace(/[\s　]/g,'').toLowerCase().includes(qs)).slice(0,8).map(([id,m])=>({id,name:m[0]})):[];return navigate('wizard')}
 if(a==='pickOwn'){captureWizard();const w=S.wizard,j=w.input.juken,m=window.JukenRoute.materials[b.dataset.id];if(m&&!j.owned.some(o=>o.id===b.dataset.id)&&j.owned.length<20)j.owned.push({id:b.dataset.id,name:m[0]});w.ownResults=[];w.ownq='';return navigate('wizard')}
 if(a==='addOwnFree'){captureWizard();const w=S.wizard,j=w.input.juken;if(w.ownq&&j.owned.length<20)j.owned.push({id:'',name:w.ownq});w.ownResults=[];w.ownq='';return navigate('wizard')}
 if(a==='removeOwn'){captureWizard();S.wizard.input.juken.owned.splice(Number(b.dataset.i),1);return navigate('wizard')}
 if(a==='jskip'||a==='jaccept'||a==='jreject'){const op={jskip:'skip',jaccept:'accept_hold',jreject:'reject_hold'}[a];return busy(async()=>{await mutate({type:'juken_adjust',planId:plan().id,ops:[{op,subject:b.dataset.subject,index:Number(b.dataset.index)}]});S.page='upper'})}
 if(a==='openTask'){S.openTask=S.openTask===b.dataset.id?null:b.dataset.id;S.taskId=S.openTask;S.partialOpen=false;S.carryMode=null;return render()}
 if(a==='carryAsk'){S.carryMode=b.dataset.mode;S.partialOpen=false;return render()}
 if(a==='carryYes'||a==='carryNo'){const mode=S.carryMode;return busy(async()=>{await mutate({type:'report',planId:plan().id,taskId:S.taskId,mode,carry:a==='carryYes'});S.openTask=null;S.carryMode=null;S.page='today'},a==='carryYes'?'記録しました。残りは、明日に入れました':'記録しました')}
 if(a==='showPartial'){S.partialOpen=true;return render()}
 if(a==='studyChip')return busy(async()=>{await mutate({type:'study_time',date:S.selectedDate||S.date,minutes:Number(b.dataset.m)})},'勉強時間を記録しました');
 if(a==='replan')return busy(async()=>{await mutate({type:'replan',planId:plan().id});S.page='today'},'組み直しました');
 if(a==='check')return busy(async()=>{await mutate({type:'check'});S.page='detail'});
 if(a==='quickDone'){S.taskId=b.dataset.id;S.openTask=b.dataset.id;return busy(async()=>{await mutate({type:'report',planId:plan().id,taskId:S.taskId,mode:'done'});S.openTask=null;S.partialOpen=false;S.page='today'},'記録しました')}
 if(a==='reportDone'||a==='reportNone')return busy(async()=>{await mutate({type:'report',planId:plan().id,taskId:S.taskId,mode:a==='reportDone'?'done':'none'});S.openTask=null;S.partialOpen=false;S.page='today'},'記録しました');
 if(a==='deleteTask'){if(!confirm('この予定を削除しますか？変更は履歴に残ります。'))return;return busy(async()=>{await mutate({type:'delete_task',planId:plan().id,taskId:S.taskId});S.page='edit'})}

 if(a==='sharePdf'){const pdf=currentPdf();if(!canSharePdf(pdf)){S.error='保存メニューを開けませんでした。「PDFを開く」から保存してください。';return renderStatus()}try{navigator.share({files:[pdf.file]}).catch(error=>{if(error.name!=='AbortError'){pdf.shareFailed=true;S.error='保存メニューを開けませんでした。PDF画面から保存してください。';render()}})}catch(error){pdf.shareFailed=true;S.error='保存メニューを開けませんでした。PDF画面から保存してください。';render()}return}
 if(a==='downloadPdf'){if(demo){const w=window.open('','_blank');if(!w){S.error='ポップアップを許可してください';return render()}w.document.write(C.printHtml(doc(),plan(),item().name,S.date));w.document.close();w.print();return}return busy(async()=>{const response=await api('app_pdf',{studentId:item().studentId,planId:plan().id});const pdf=preparePdfData(response);if(S.pdf)URL.revokeObjectURL(S.pdf.url);S.pdf=pdf})}

});
$('phone').addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();if(S.busy)return;const v=Object.fromEntries(new FormData(f)),name=f.dataset.form;
 if(name==='wizard'){const wf=$('wizardForm'),bad=wf&&Array.from(wf.elements).find(e=>e.willValidate&&!e.validity.valid);if(bad){const dt=bad.closest('details');if(dt)dt.open=true;bad.focus();bad.reportValidity();return}captureWizard();const w=S.wizard;if(w.step<5){if(w.step===2&&(w.input.goal<w.input.start||w.input.start<S.date)){S.error='開始日・終了日を確認してください';return renderStatus()}if(w.step===3&&w.input.type==='juken'){const j=w.input.juken||{};if(!j.band){S.error='志望校を選んでください';return renderStatus()}if(!j.examYm){S.error='入試の年月を入れてください';return renderStatus()}if(!j.subjects.length){S.error='科目を1つ以上、選んでください';return renderStatus()}}if(w.step===3&&w.input.type!=='juken'&&w.input.materials.some(m=>m.to<m.from)){S.error='教材の終わりは始まり以上にしてください';return renderStatus()}w.step=nextStep(w,1);saveDraft();render();$('content').scrollTop=0;return}return busy(async()=>{await mutate({type:w.rebuildId?'rebuild':'create',planId:w.rebuildId,input:w.input.type==='juken'?jukenInput(w.input):w.input});localStorage.removeItem(draftKey());S.wizard=null;S.planId=doc().activeId;S.selectedDate=S.date;S.page=S.role==='teacher'?'plan':'today'})}
 if(jukenFormHandlers[name])return busy(async()=>{await mutate(jukenFormHandlers[name](v));S.page='upper'});
 return busy(async()=>{if(name==='roadmap'){const months=v.months.split('\n').filter(s=>s.trim()).map(line=>{const [month,...text]=line.split('|');return {month:month.trim(),text:text.join('|').trim()}});await mutate({type:'roadmap',planId:plan().id,months});S.page='plan'}if(name==='studyMin'){await mutate({type:'study_time',date:S.selectedDate||S.date,minutes:Number(v.minutes)});S.toast='勉強時間を記録しました'}if(name==='partial'){await mutate({type:'report',planId:plan().id,taskId:S.taskId,mode:'partial',position:Number(v.position)});S.openTask=null;S.partialOpen=false;S.page='today'}if(name==='feedback'){await mutate({type:'feedback',text:v.text});S.page='detail'}if(name==='settings'){await mutate({type:'settings',settings:{todo:v.todo,report:v.same?v.todo:v.report,same:!!v.same,wd:Number(v.wd),wt:v.wt,notifyTo:v.notifyTo||doc().settings.notifyTo||'auto'}});S.page='plan'}if(name==='teacherSettings'){const result=await api('app_teacher_settings',{settings:{wd:Number(v.wd),wt:v.wt,late:v.late==='true',lateDays:Number(v.lateDays),edited:v.edited==='true',mode:v.mode}});S.teacherSettings=result.settings;S.page='students'}if(name==='editTask'){await mutate({type:S.taskId?'edit_task':'add_task',planId:plan().id,taskId:S.taskId,...v,minutes:Number(v.minutes)});S.page='edit'}if(name==='moveDay'){if(!confirm('今日の未記録の予定を'+v.date+'へ移しますか？'))return;await mutate({type:'move_day',planId:plan().id,date:v.date});S.page='plan'}})
});
async function start(){if(demo)return busy(boot,'');try{if(typeof liff==='undefined')throw Error('LINEの読み込みに失敗しました。通信を確認して開き直してください');await liff.init({liffId:CONFIG.liffId});if(!liff.isLoggedIn()){liff.login();return}await busy(boot,'')}catch(e){S.error=e.message;render()}}
start();
